"""
define generic base classes for pandas objects

Python36中pandas1.0.1库简版
仅实现print(pd.DataFrame)时格式与RPA历史版本保持一致
"""


# define abstract base classes to enable isinstance type checking on our
# objects
def create_pandas_abc_type(name, attr, comp):
    # https://github.com/python/mypy/issues/1006
    # error: 'classmethod' used with a non-method
    @classmethod  # type: ignore
    def _check(cls, inst) -> bool:
        return getattr(inst, attr, "_typ") in comp

    dct = dict(__instancecheck__=_check, __subclasscheck__=_check)
    meta = type("ABCBase", (type,), dct)
    return meta(name, tuple(), dct)


ABCIndexClass = create_pandas_abc_type(
    "ABCIndexClass",
    "_typ",
    (
        "index",
        "int64index",
        "rangeindex",
        "float64index",
        "uint64index",
        "multiindex",
        "datetimeindex",
        "timedeltaindex",
        "periodindex",
        "categoricalindex",
        "intervalindex",
    ),
)
ABCMultiIndex = create_pandas_abc_type("ABCMultiIndex", "_typ", ("multiindex",))
ABCSeries = create_pandas_abc_type("ABCSeries", "_typ", ("series",))

ABCSparseArray = create_pandas_abc_type(
    "ABCSparseArray", "_subtyp", ("sparse_array", "sparse_series")
)
